[Thinking]
**Crafting functional code**

I’m thinking about placing placeholders in my code. I want to provide simple JavaScript for navigation toggle and an FAQ accordion, and maybe a lightbox for the gallery that’s minimal. My goal is to craft something around 300-400 lines long — functional but not overly lengthy. I’ll focus on keeping it straightforward so that it’s easy to understand and operate. Let’s get started on that!
[/Thinking]

<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>CS:GO Community Hub</title>
  <meta name="description" content="A fan-made CS:GO website featuring news, maps, weapons, tips, and community events." />
  <meta name="theme-color" content="#0c1117" />
  <style>
    :root{
      --bg:#0b0f14;
      --bg2:#111827;
      --card:#0f1623;
      --muted:#94a3b8;
      --text:#e5e7eb;
      --primary:#22c55e;
      --accent:#60a5fa;
      --warn:#f59e0b;
      --danger:#ef4444;
      --border:#1f2937;
      --shadow:0 10px 30px rgba(0,0,0,.35);
      --radius:14px;
      --radius-sm:10px;
      --radius-lg:22px;
    }
    *{box-sizing:border-box}
    html,body{margin:0;padding:0;background:linear-gradient(180deg,#0b0f14 0%,#0a0e13 100%);color:var(--text);font-family:system-ui,-apple-system,Segoe UI,Roboto,Ubuntu,Cantarell,"Helvetica Neue",Arial,"Noto Sans",sans-serif;line-height:1.6}
    a{color:var(--accent);text-decoration:none}
    a:hover{text-decoration:underline}
    img{max-width:100%;display:block}
    .container{max-width:1200px;margin:0 auto;padding:0 20px}
    header{
      position:sticky;top:0;z-index:50;
      backdrop-filter:saturate(1.2) blur(10px);
      background:linear-gradient(180deg,rgba(15,22,35,.9),rgba(15,22,35,.65));
      border-bottom:1px solid var(--border)
    }
    .nav{
      display:flex;align-items:center;justify-content:space-between;gap:16px;padding:14px 0
    }
    .brand{display:flex;align-items:center;gap:10px;font-weight:800;letter-spacing:.5px}
    .brand .logo{
      width:36px;height:36px;border-radius:10px;background:
        conic-gradient(from 220deg at 50% 50%, #2dd4bf, #22c55e 45%, #60a5fa 75%, #2dd4bf);
      position:relative;box-shadow:0 0 0 2px rgba(255,255,255,.06) inset, var(--shadow)
    }
    .brand .logo::after{
      content:"";position:absolute;inset:6px;border-radius:8px;background:#0b0f14
    }
    .brand span{font-size:18px}
    .nav-links{display:flex;gap:18px;align-items:center}
    .nav-links a{color:var(--text);opacity:.88}
    .nav-cta{
      background:linear-gradient(135deg,#22c55e,#16a34a);color:#07120a;
      padding:10px 14px;border-radius:10px;font-weight:700;box-shadow:var(--shadow)
    }
    .menu-btn{display:none;background:#0f1623;border:1px solid var(--border);color:var(--text);padding:8px 10px;border-radius:10px}
    @media (max-width:900px){
      .nav-links{display:none}
      .menu-btn{display:inline-flex}
      .mobile-menu{display:none;flex-direction:column;gap:10px;padding-bottom:12px}
      .mobile-menu.open{display:flex}
      .mobile-menu a{padding:8px 10px;border-radius:8px;background:#0f1623;border:1px solid var(--border)}
    }

    /* Hero */
    .hero{
      position:relative;overflow:hidden;border-bottom:1px solid var(--border)
    }
    .hero-wrap{display:grid;grid-template-columns:1.15fr .85fr;gap:28px;align-items:center;padding:48px 0}
    @media (max-width:1000px){.hero-wrap{grid-template-columns:1fr}}
    .hero h1{font-size:44px;line-height:1.1;margin:6px 0 12px;font-weight:900;letter-spacing:.2px}
    .hero p{color:var(--muted);font-size:18px;margin:0 0 14px}
    .badge{
      display:inline-flex;gap:8px;align-items:center;
      padding:6px 10px;border:1px solid var(--border);border-radius:999px;background:#0f1623
    }
    .hero-cta{display:flex;gap:12px;flex-wrap:wrap;margin-top:12px}
    .btn{
      display:inline-flex;align-items:center;gap:10px;border-radius:12px;border:1px solid var(--border);
      background:#101827;color:var(--text);padding:12px 14px;font-weight:700
    }
    .btn.primary{background:linear-gradient(135deg,#22c55e,#10b981);color:#07120a;border-color:transparent}
    .btn.ghost{background:#0f1623}
    .meta{display:flex;gap:18px;flex-wrap:wrap;color:var(--muted);font-size:14px;margin-top:14px}
    .hero-card{
      border:1px solid var(--border);border-radius:var(--radius-lg);overflow:hidden;background:radial-gradient(1000px 400px at 120% -10%,rgba(34,197,94,.18),transparent 60%), #0f1623
    }
    .hero-media{
      aspect-ratio:16/9;background:linear-gradient(120deg,#0b1220,#0b0f14);
      display:grid;place-items:center;position:relative
    }
    .crosshair{
      width:110px;height:110px;border:2px solid rgba(255,255,255,.08);border-radius:50%;
      position:relative
    }
    .crosshair::before,.crosshair::after{
      content:"";position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);
      width:2px;height:90%;background:linear-gradient(#22c55e,#059669);border-radius:2px;opacity:.7
    }
    .crosshair::after{transform:translate(-50%,-50%) rotate(90deg)}
    .video-bar{display:flex;gap:10px;padding:12px;background:#0c131f;border-top:1px solid var(--border)}
    .tag{font-size:12px;border:1px solid var(--border);padding:6px 8px;border-radius:999px;background:#0b111a;color:var(--muted)}

    /* Sections */
    section{padding:48px 0;border-bottom:1px solid var(--border)}
    .section-head{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:18px}
    .section-head h2{margin:0;font-size:28px}
    .grid{display:grid;gap:16px}
    .grid.cards{grid-template-columns:repeat(3,1fr)}
    .grid.quad{grid-template-columns:repeat(4,1fr)}
    @media (max-width:1000px){.grid.cards{grid-template-columns:repeat(2,1fr)}.grid.quad{grid-template-columns:repeat(2,1fr)}}
    @media (max-width:600px){.grid.cards,.grid.quad{grid-template-columns:1fr}}
    .card{
      background:#0f1623;border:1px solid var(--border);border-radius:var(--radius);
      overflow:hidden;box-shadow:var(--shadow);transition:transform .2s ease, border-color .2s ease
    }
    .card:hover{transform:translateY(-2px);border-color:#203047}
    .card .cover{aspect-ratio:16/9;background:linear-gradient(120deg,#0b1220,#0d1421)}
    .card .content{padding:14px}
    .card h3{margin:0 0 6px}
    .card p{margin:0;color:var(--muted)}
    .pill{display:inline-flex;gap:6px;align-items:center;font-size:12px;padding:4px 8px;border-radius:999px;border:1px solid var(--border);background:#0b111a;color:var(--muted)}

    /* Weapons */
    .weapon{display:flex;gap:14px;align-items:center;padding:12px}
    .weapon img{width:72px;height:42px;object-fit:cover;border-radius:10px;border:1px solid var(--border);background:#0c121d}
    .stat{height:8px;background:#0b111a;border-radius:999px;overflow:hidden;border:1px solid var(--border)}
    .stat > span{display:block;height:100%;background:linear-gradient(90deg,#22c55e,#16a34a)}

    /* Download block */
    .download{
      display:grid;grid-template-columns:1.2fr .8fr;gap:18px;align-items:center
    }
    @media (max-width:900px){.download{grid-template-columns:1fr}}
    .panel{
      background:linear-gradient(140deg,rgba(96,165,250,.12),rgba(2,6,23,.6)), #0f1623;
      border:1px solid var(--border);border-radius:var(--radius-lg);padding:16px
    }
    .panel .row{display:flex;gap:12px;flex-wrap:wrap;margin-top:10px}
    .note{font-size:13px;color:var(--muted)}

    /* FAQ */
    .faq{display:grid;gap:10px}
    .qa{
      background:#0f1623;border:1px solid var(--border);border-radius:12px;overflow:hidden
    }
    .qa button{
      width:100%;text-align:left;padding:14px;background:transparent;border:0;color:var(--text);
      display:flex;justify-content:space-between;align-items:center;cursor:pointer
    }
    .qa .answer{padding:0 14px 14px;display:none;color:var(--muted)}
    .qa.open .answer{display:block}
    .chev{transition:transform .2s}
    .qa.open .chev{transform:rotate(180deg)}

    footer{
      padding:28px 0;color:var(--muted)
    }
    .foot-wrap{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:10px;border-top:1px solid var(--border);padding-top:18px}
    .social{display:flex;gap:10px}
    .social a{display:inline-flex;align-items:center;justify-content:center;width:36px;height:36px;border-radius:10px;background:#0f1623;border:1px solid var(--border)}
  </style>
</head>
