        <a href="#news">News</a>
        <a href="#maps">Maps</a>
        <a href="#weapons">Weapons</a>
        <a href="#guides">Guides</a>
        <a href="#events">Events</a>
        <a href="#download" class="nav-cta">Play Now</a>
      </nav>
      <button class="menu-btn" id="menuBtn" aria-expanded="false" aria-controls="mobileMenu">Menu</button>
    </div>
    <div class="container mobile-menu" id="mobileMenu" role="dialog" aria-label="Mobile menu">
      <a href="#news">News</a>
      <a href="#maps">Maps</a>
      <a href="#weapons">Weapons</a>
      <a href="#guides">Guides</a>
      <a href="#events">Events</a>
      <a href="#download">Play Now</a>
    </div>
  </header>

