    .section-head{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:18px}
    .section-head h2{margin:0;font-size:28px}
    .grid{display:grid;gap:16px}
    .grid.cards{grid-template-columns:repeat(3,1fr)}
    .grid.quad{grid-template-columns:repeat(4,1fr)}
    @media (max-width:1000px){.grid.cards{grid-template-columns:repeat(2,1fr)}.grid.quad{grid-template-columns:repeat(2,1fr)}}
    @media (max-width:600px){.grid.cards,.grid.quad{grid-template-columns:1fr}}
    .card{
      background:#0f1623;border:1px solid var(--border);border-radius:var(--radius);
      overflow:hidden;box-shadow:var(--shadow);transition:transform .2s ease, border-color .2s ease
    }
    .card:hover{transform:translateY(-2px);border-color:#203047}
    .card .cover{aspect-ratio:16/9;background:linear-gradient(120deg,#0b1220,#0d1421)}
    .card .content{padding:14px}
    .card h3{margin:0 0 6px}
    .card p{margin:0;color:var(--muted)}
    .pill{display:inline-flex;gap:6px;align-items:center;font-size:12px;padding:4px 8px;border-radius:999px;border:1px solid var(--border);background:#0b111a;color:var(--muted)}

    /* Weapons */
    .weapon{display:flex;gap:14px;align-items:center;padding:12px}
    .weapon img{width:72px;height:42px;object-fit:cover;border-radius:10px;border:1px solid var(--border);background:#0c121d}
    .stat{height:8px;background:#0b111a;border-radius:999px;overflow:hidden;border:1px solid var(--border)}
    .stat > span{display:block;height:100%;background:linear-gradient(90deg,#22c55e,#16a34a)}

    /* Download block */
    .download{
      display:grid;grid-template-columns:1.2fr .8fr;gap:18px;align-items:center
    }
    @media (max-width:900px){.download{grid-template-columns:1fr}}
    .panel{
      background:linear-gradient(140deg,rgba(96,165,250,.12),rgba(2,6,23,.6)), #0f1623;
      border:1px solid var(--border);border-radius:var(--radius-lg);padding:16px
    }
    .panel .row{display:flex;gap:12px;flex-wrap:wrap;margin-top:10px}
    .note{font-size:13px;color:var(--muted)}

    /* FAQ */
    .faq{display:grid;gap:10px}
    .qa{
      background:#0f1623;border:1px solid var(--border);border-radius:12px;overflow:hidden
    }
    .qa button{
      width:100%;text-align:left;padding:14px;background:transparent;border:0;color:var(--text);
      display:flex;justify-content:space-between;align-items:center;cursor:pointer
    }
    .qa .answer{padding:0 14px 14px;display:none;color:var(--muted)}
    .qa.open .answer{display:block}
    .chev{transition:transform .2s}
    .qa.open .chev{transform:rotate(180deg)}

    footer{
      padding:28px 0;color:var(--muted)
    }
    .foot-wrap{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:10px;border-top:1px solid var(--border);padding-top:18px}
    .social{display:flex;gap:10px}
    .social a{display:inline-flex;align-items:center;justify-content:center;width:36px;height:36px;border-radius:10px;background:#0f1623;border:1px solid var(--border)}
  </style>
</head>
